def compute_model_placement(gpu_num, models):
    """
    Greedy placement (place each model on the GPU minimizing resulting KVPR)
    refined by a global local search that applies the best move or swap of
    models between any two GPUs that lowers the max KVPR. Two initial
    orderings (pressure-desc and size-desc) are tried, keeping the best.
    """
    def kvpr(p, f):
        return p / f if f > 0 else float('inf')

    def build(order):
        placement = {g: [] for g in range(gpu_num)}
        free_mem = [GPU_MEM_SIZE] * gpu_num
        pressure = [0.0] * gpu_num
        for model in order:
            best_idx, best_k = None, float('inf')
            for g in range(gpu_num):
                rem = free_mem[g] - model.model_size
                if rem > 0:
                    k = (pressure[g] + model.req_rate / model.slo) / rem
                    if k < best_k:
                        best_k, best_idx = k, g
            if best_idx is None:
                return None, None, None
            placement[best_idx].append(model)
            pressure[best_idx] += model.req_rate / model.slo
            free_mem[best_idx] -= model.model_size
        return placement, free_mem, pressure

    def refine(placement, free_mem, pressure):
        def others_max(exclude):
            return max(kvpr(pressure[g], free_mem[g])
                       for g in range(gpu_num) if g not in exclude)
        improved = True
        while improved:
            improved = False
            cur = max(kvpr(pressure[g], free_mem[g]) for g in range(gpu_num))
            best = None
            for src in range(gpu_num):
                for m1 in placement[src]:
                    p1, s1 = m1.req_rate / m1.slo, m1.model_size
                    for dst in range(gpu_num):
                        if dst == src or s1 > free_mem[dst]:
                            continue
                        cand = max(kvpr(pressure[src] - p1, free_mem[src] + s1),
                                   kvpr(pressure[dst] + p1, free_mem[dst] - s1),
                                   others_max((src, dst)))
                        if cand < cur and (best is None or cand < best[0]):
                            best = (cand, 'move', src, dst, m1, None)
            for src in range(gpu_num):
                for dst in range(src + 1, gpu_num):
                    for m1 in placement[src]:
                        for m2 in placement[dst]:
                            d = m1.model_size - m2.model_size
                            if d > free_mem[dst] or -d > free_mem[src]:
                                continue
                            p1 = m1.req_rate / m1.slo
                            p2 = m2.req_rate / m2.slo
                            cand = max(kvpr(pressure[src] - p1 + p2, free_mem[src] - d),
                                       kvpr(pressure[dst] - p2 + p1, free_mem[dst] + d),
                                       others_max((src, dst)))
                            if cand < cur and (best is None or cand < best[0]):
                                best = (cand, 'swap', src, dst, m1, m2)
            if best:
                _, kind, src, dst, m1, m2 = best
                if kind == 'move':
                    placement[src].remove(m1); placement[dst].append(m1)
                    pressure[src] -= m1.req_rate / m1.slo
                    free_mem[src] += m1.model_size
                    pressure[dst] += m1.req_rate / m1.slo
                    free_mem[dst] -= m1.model_size
                else:
                    placement[src].remove(m1); placement[src].append(m2)
                    placement[dst].remove(m2); placement[dst].append(m1)
                    pressure[src] += m2.req_rate / m2.slo - m1.req_rate / m1.slo
                    free_mem[src] += m2.model_size - m1.model_size
                    pressure[dst] += m1.req_rate / m1.slo - m2.req_rate / m2.slo
                    free_mem[dst] += m1.model_size - m2.model_size
                improved = True
        return placement

    orders = [sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
              sorted(models, key=lambda m: m.model_size, reverse=True)]
    best_place, best_val = None, float('inf')
    for order in orders:
        placement, free_mem, pressure = build(order)
        if placement is None:
            raise ValueError("Model cannot fit on any GPU")
        placement = refine(placement, free_mem, pressure)
        val = max(kvpr(pressure[g], free_mem[g]) for g in range(gpu_num))
        if val < best_val:
            best_val, best_place = val, placement
    return best_place

